using ModelContextProtocol.Server;
using System.Text.Json;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<DevTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class DevTools
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add"), Description("Adds two numbers.")]
    public static string Add(double a, double b) => $"Result: {a + b}";
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        Description = "Returns the current application configuration.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "App Version",
        Description = "Returns the application version information.")]
    public static string GetVersion()
    {
        var version = new { Version = "2.1.0", BuildDate = "2026-07-14", Runtime = Environment.Version.ToString() };
        return JsonSerializer.Serialize(version, new JsonSerializerOptions { WriteIndented = true });
    }
}

